-- Oscar Patel exercise encyclopedia, part 2 of 2: the draft protocol "Oscar Patel — Master Exercise Encyclopedia".
--
-- Ten days: days 1 to 9 are the catalogue's nine categories, day 10 is a suggested 37-minute session. 123 items, 24 of them hidden
-- (the research-only techniques, which the web and the app do not render) and 4 safety rules. It is a draft: is_enabled = false,
-- is_public = false, and it has no owner (user_id null), because the Staging owner has no counterpart in Production. Publish or
-- assign it from the admin protocol editor when it has been reviewed. Rule titles are the current Staging wording: the two
-- "don't" rules share no keywords with the exercise names, so the editor's contradiction check reports none. The cover image is
-- not part of this change.
--
-- Needs part 1 (20261026160000) and the 17 existing catalog activities it links to (chin tuck, cobra, glute bridge and so on).
-- If any activity it uses is missing, it fails naming them and writes nothing. Idempotent: skipped when the protocol id already exists, so it is a no-op
-- on Staging, which already holds this exact protocol under the owner who created it. The items are inserted with
-- created_by null; on a protocol with no owner the calendar sync has nobody to push events for.

do $oscar_protocol$
declare
  missing text;
  items jsonb := $oscar_items$[
{"id":"325f4040-4999-5bd3-92e4-899661f576c9","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Zygotape","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Facial taping and passive practices","duration_minutes":1,"day_number":9,"sort_order":10,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_zygotape","notes":"Research-only, not for self-guided use. Described in Oscar's materials: Taping intended to change tension around the cheeks. Documented dose: Nightly in the archived routine. Reshaping the face with tape is not established. Skin irritation is possible and tape should never cover the mouth during sleep.","hidden":true,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"3903c944-abec-5d1c-8584-d879ef2a1a73","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Foot Ball Rolling","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"Foot, lower-body and fascia release","scheduled_time":"07:00:00","duration_minutes":2,"day_number":2,"sort_order":10,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_foot_ball_rolling","notes":"Dose: 30–60 seconds per foot.\n1. Put a ball under the sole of your foot, holding on to a wall or chair for balance.\n2. Roll slowly from the heel toward the toes.\n3. Move the ball across the arch and the ball of the foot.\n4. Pause on tight spots with light pressure.\n5. Repeat on the other foot.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"62ef0ab7-0e05-5d92-856f-550fc7fc4041","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Light Bouncing","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"Full-body activation, spirals and twists","scheduled_time":"07:00:00","duration_minutes":3,"day_number":1,"sort_order":10,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_light_bouncing","notes":"Dose: 2–3 minutes.\n1. Stand upright with your feet hip-width apart and your shoulders relaxed.\n2. Rise a little onto the balls of your feet.\n3. Let the heels drop and rebound in an easy rhythm, with soft knees.\n4. Stay relaxed through the shoulders and jaw; the bounce is small and quiet.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"697dcdba-8fec-5329-b5e6-329d37c3a5dc","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Supported Neck Flexion (Chin Nods)","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"Neck training","scheduled_time":"07:00:00","duration_minutes":3,"day_number":6,"sort_order":10,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_supported_neck_flexion_chin_nods","notes":"Dose: Oscar's archive lists 3 sets of 15–30 reps with 3-second holds; this beginner form uses small supported nods and no resistance.\n1. Lie on your back with your head fully supported on a pillow.\n2. Make a small, gentle nodding movement, bringing your chin toward your throat.\n3. Hold for about 3 seconds.\n4. Let the head settle back under control.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"909cdaa6-4361-5b87-956c-31dd21ebdb37","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Thumbpulling","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Cranial and palate techniques (research-only)","duration_minutes":2,"day_number":8,"sort_order":10,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_palate_thumb_pressure","notes":"Existing research-only catalog activity (Palate Thumb Pressure). Upward and outward thumb pressure on the hard palate with chin tuck; the archive says 2 minutes, sometimes repeated. Research-only: not enabled for self-guided use.","hidden":true,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"948d429a-90bc-5d17-8e5a-551ff91074d4","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Chin tuck","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"Posture, pelvis and spine","scheduled_time":"07:00:00","duration_minutes":2,"day_number":3,"sort_order":10,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_chin_tuck","notes":"10–15 reps, often twice daily. This is an existing catalog activity; its full steps are on the activity.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"ca140ebb-d42c-5273-a030-b76a3c77e775","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Orbicularis Oris Popping","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Facial muscles and soft-tissue massage","scheduled_time":"07:00:00","duration_minutes":2,"day_number":5,"sort_order":10,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_orbicularis_oris_popping","notes":"Dose: 2 sets of 10.\n1. Draw your cheeks gently inward.\n2. Close the lips to make a light suction.\n3. Release the lips so they pop softly.\n4. Relax your face between reps.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"d016ad3c-ce59-5a5e-96f6-d0877472aeb7","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Resting Tongue Posture (Mewing)","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Tongue training, swallowing and chewing","scheduled_time":"07:00:00","duration_minutes":2,"day_number":4,"sort_order":10,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_resting_tongue_posture_mewing","notes":"Dose: A habit through the day; no timed sets.\n1. Sit or stand with your head comfortably aligned.\n2. Let the jaw hang loose.\n3. Close your lips without pressing them together.\n4. Rest the tongue tip just behind the upper front teeth, without pushing on them, with the wider tongue resting lightly against the palate.\n5. Keep breathing quietly through the nose.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"daaea72d-5bf3-5c1d-af5b-5380532a78a6","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Buteyko Breathing","item_type":"activity","kind":"action","category":"do","subtype":"wellness","group_name":"Breathwork and nervous-system exercises","scheduled_time":"07:00:00","duration_minutes":5,"day_number":7,"sort_order":10,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_buteyko_breathing","notes":"Dose: Archived: 5–10 cycles.\n1. Sit upright and relaxed.\n2. Breathe quietly through your nose.\n3. After a normal breath out, take a short, comfortable pause. It should never feel like a struggle.\n4. Return to quiet nasal breathing and let the breath settle before the next cycle.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"f189adbb-0014-51b8-8f77-0bc86db76276","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Light Bouncing","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"1. Warm up (5 min)","scheduled_time":"07:00:00","duration_minutes":2,"day_number":10,"sort_order":10,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_light_bouncing","notes":"Suggested complete session: a synthesis of lower-risk elements from the catalogue, not an exact routine published by Oscar. Dose: 2–3 minutes.\n1. Stand upright with your feet hip-width apart and your shoulders relaxed.\n2. Rise a little onto the balls of your feet.\n3. Let the heels drop and rebound in an easy rhythm, with soft knees.\n4. Stay relaxed through the shoulders and jaw; the bounce is small and quiet.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"00dbe8d7-6e8f-5ac9-aef7-70c0f10cc391","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Orbicularis Oculi Activation","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Facial muscles and soft-tissue massage","scheduled_time":"07:03:00","duration_minutes":3,"day_number":5,"sort_order":20,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_orbicularis_oculi_activation","notes":"Dose: Oscar describes 2 sets of 20.\n1. Close your eyelids gently.\n2. Squeeze lightly without wrinkling or pulling the skin.\n3. Release fully and open your eyes.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"5ce0967a-943d-598e-910f-142d48d3623a","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Alternate Nostril Breathing","item_type":"activity","kind":"action","category":"do","subtype":"wellness","group_name":"Breathwork and nervous-system exercises","scheduled_time":"07:06:00","duration_minutes":4,"day_number":7,"sort_order":20,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_alternate_nostril_breathing","notes":"Dose: 2–5 minutes.\n1. Sit upright and relaxed.\n2. Gently close the right nostril with your thumb.\n3. Breathe in slowly through the left nostril.\n4. Close the left nostril, release the right and breathe out slowly through it.\n5. Breathe in through the right, then out through the left. Continue in this way.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"78891d34-67cd-5a39-80a3-b68c03369e91","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Full-Body Spiral Reaches","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"Full-body activation, spirals and twists","scheduled_time":"07:04:00","duration_minutes":3,"day_number":1,"sort_order":20,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_full_body_spiral_reaches","notes":"Dose: 10 reps in total (5 each side).\n1. Stand with your feet hip-width apart.\n2. Reach one arm diagonally across your body.\n3. Allow your chest and upper spine to follow the reach, and the opposite hip to rotate comfortably.\n4. Come back to centre and reach with the other arm.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"7f046bd5-cc77-50a3-9468-3f462d2ccaad","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"STO method","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Facial taping and passive practices","duration_minutes":1,"day_number":9,"sort_order":20,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_sto_method","notes":"Research-only, not for self-guided use. Described in Oscar's materials: A separate facial taping and positioning method referenced in his course. Documented dose: Nightly in the archived routine. Not established; details are not publicly verified. Do not tape the mouth shut during sleep.","hidden":true,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"8ae46c50-dd57-5462-bccc-321c1b5d5cdb","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Calf Rolling","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"Foot, lower-body and fascia release","scheduled_time":"07:03:00","duration_minutes":2,"day_number":2,"sort_order":20,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_calf_rolling","notes":"Dose: 30 seconds per side.\n1. Sit with one calf on a roller or ball, hands behind you.\n2. Roll from just above the ankle toward just below the knee.\n3. Turn the leg slightly in and out to reach the sides.\n4. Repeat with the other calf.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"a459d643-150b-52bb-8f3f-fb111060fc0c","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Suction Mewing","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Tongue training, swallowing and chewing","scheduled_time":"07:03:00","duration_minutes":1,"day_number":4,"sort_order":20,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_suction_mewing","notes":"Dose: No fixed count.\n1. Close your lips gently.\n2. Swallow your saliva naturally.\n3. Notice how the tongue lightly touches the palate.\n4. Hold a comfortable, light suction without pushing hard.\n5. Keep breathing normally and stop if it is uncomfortable.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"b0602886-5b73-505a-acb9-11e3b3eb32a4","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Side-Neck Isometric Press","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"Neck training","scheduled_time":"07:04:00","duration_minutes":3,"day_number":6,"sort_order":20,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_side_neck_isometric_press","notes":"Dose: Archive: 3 × 15–30 each side (bench version); beginner form here is a 10-second isometric press.\n1. Sit or stand upright.\n2. Rest one palm against the side of your head.\n3. Press the head gently into the hand without letting the neck move.\n4. Hold for about 10 seconds, then relax.\n5. Repeat on the other side.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"d5cdb6bb-76dd-5d46-aa70-7734b3d378ca","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Three-direction thumbpulling","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Cranial and palate techniques (research-only)","duration_minutes":2,"day_number":8,"sort_order":20,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_three_direction_thumbpulling","notes":"Research-only, not for self-guided use. Described in Oscar's materials: Thumb pressure on the palate in three different directions. Documented dose: 60 seconds per direction. Forceful manual palate pressure is not an established treatment and can cause dental movement, gum injury and jaw pain. Needs dental or orthodontic review.","hidden":true,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"d851c558-5f8f-50ad-abe3-8859b11dc3c7","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Wall Angels","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"Posture, pelvis and spine","scheduled_time":"07:03:00","duration_minutes":3,"day_number":3,"sort_order":20,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_wall_angels","notes":"Dose: 10 reps.\n1. Stand with your back against a wall, feet slightly forward.\n2. Bring your arms into a goalpost shape against the wall.\n3. Slowly slide your arms upward without your lower ribs flaring.\n4. Slide back down with control.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
