{"id":"612ae655-0806-5b8a-9a8e-efc4272d84ef","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Tongue Chewing","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Tongue training, swallowing and chewing","scheduled_time":"07:07:00","duration_minutes":5,"day_number":4,"sort_order":40,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_tongue_chewing","notes":"Dose: 5 minutes in the archived routine; some versions use 60 seconds × 2–3 sets.\n1. Soften a small piece of sugar-free chewing gum.\n2. Position it against the roof of your mouth.\n3. Flatten it with the broad surface of your tongue.\n4. Gather it back into a small piece.\n5. Repeat without clenching your teeth.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"8b4253e9-4181-5889-836b-b350d3e43dc3","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Backward Nasal Breathing Cue","item_type":"activity","kind":"action","category":"do","subtype":"wellness","group_name":"Breathwork and nervous-system exercises","scheduled_time":"07:15:00","duration_minutes":2,"day_number":7,"sort_order":40,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_backward_nasal_breathing_cue","notes":"Dose: No fixed count.\n1. Breathe gently through your nose.\n2. Imagine the air travelling backward toward your throat rather than up into your shoulders.\n3. Do not lift your shoulders or chest.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"c883449d-3f12-52cc-a0b5-c4270e2a2e2f","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Neck Warm-up Rotation","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"Neck training","scheduled_time":"07:12:00","duration_minutes":2,"day_number":6,"sort_order":40,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_neck_warm_up_rotation","notes":"Dose: As comfortable.\n1. Sit or stand tall with relaxed shoulders.\n2. Turn your head gently toward the left.\n3. Come back to the middle.\n4. Turn gently toward the right, without forcing a full circle.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"d263d109-870d-5c6b-8e80-d1d88d7d6f68","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Foot Ball Rolling","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"2. Release (8–10 min)","scheduled_time":"07:05:00","duration_minutes":2,"day_number":10,"sort_order":40,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_foot_ball_rolling","notes":"Suggested complete session: a synthesis of lower-risk elements from the catalogue, not an exact routine published by Oscar. Dose: 30–60 seconds per foot.\n1. Put a ball under the sole of your foot, holding on to a wall or chair for balance.\n2. Roll slowly from the heel toward the toes.\n3. Move the ball across the arch and the ball of the foot.\n4. Pause on tight spots with light pressure.\n5. Repeat on the other foot.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"f0aae5d4-f0ac-5e04-beb5-e5df2c1760c6","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Buccinator taping","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Facial taping and passive practices","duration_minutes":1,"day_number":9,"sort_order":40,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_buccinator_taping","notes":"Research-only, not for self-guided use. Described in Oscar's materials: Tape placed to change cheek-muscle activation. Documented dose: not specified. Not established; skin irritation is possible and tape should never block the mouth during sleep.","hidden":true,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
