{"id":"fc08a45d-ef97-5c23-8dd1-ee4003a2be83","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Hands-Free Fascia-Pulling Twist","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"Full-body activation, spirals and twists","scheduled_time":"07:12:00","duration_minutes":2,"day_number":1,"sort_order":40,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_hands_free_fascia_pulling_twist","notes":"Dose: A few slow turns each side; Oscar gives no verified total count.\n1. Step into a lunge with your weight over the front knee and the back heel lifted.\n2. Relax your face and breathe quietly through the nose. Keep your hands free (no thumbs in the mouth).\n3. Slowly turn your head first, then your spine, then your hips, within a comfortable range.\n4. Let the back heel pivot outward naturally as the body turns.\n5. Return to centre, then repeat on the other side.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"083ab78f-5f04-5307-97dc-c10b715f244f","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Quadriceps Release","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"Foot, lower-body and fascia release","scheduled_time":"07:12:00","duration_minutes":2,"day_number":2,"sort_order":50,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_quadriceps_release","notes":"Dose: 30 seconds per side.\n1. Lie face down with the roller under the front of one thigh, forearms supporting you.\n2. Roll from just below the hip to just above the knee. Avoid pressing on the kneecap or joint.\n3. Repeat on the other thigh.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
