{"id":"33cc50f0-73a4-5f06-b5c9-f7493a167b21","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Orbicularis Tapping","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Facial muscles and soft-tissue massage","scheduled_time":"07:16:00","duration_minutes":2,"day_number":5,"sort_order":60,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_orbicularis_tapping","notes":"Dose: Not specified.\n1. Locate the bony ridge around your eye socket.\n2. Tap very lightly over the brow and the outer edge of the orbital bone.\n3. Never press on the eye itself.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"37b1aeda-e192-50a1-ad83-3f5229531501","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Neck Isometrics","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"Neck training","scheduled_time":"07:17:00","duration_minutes":4,"day_number":6,"sort_order":60,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_neck_isometrics","notes":"Dose: 10-second holds.\n1. Sit or stand upright with relaxed shoulders.\n2. Place a hand on your forehead, the back of your head or the side of your head.\n3. Press gently into the hand without the head actually moving.\n4. Hold for about 10 seconds.\n5. Relax, then try the other directions.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
