{"id":"6200a767-da3a-5d09-8b76-eb72bece1ea8","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Incisor chewing","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Tongue training, swallowing and chewing","duration_minutes":2,"day_number":4,"sort_order":160,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_incisor_chewing","notes":"Research-only, not for self-guided use. Described in Oscar's materials: Deliberate chewing with the front teeth. Documented dose: 2 minutes before meals. Chewing with the front teeth can load the incisors and the jaw joint unusually. Needs dental review before any use.","hidden":true,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"d2d87f0b-1ab0-546d-8cbe-ef976908cf85","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Barefoot sprinting","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"Posture, pelvis and spine","duration_minutes":3,"day_number":3,"sort_order":160,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_barefoot_sprinting","notes":"Research-only, not for self-guided use. Described in Oscar's materials: Mentioned by Oscar without a complete, verified progression. Documented dose: not specified. No safe, verified progression is available. Sprinting barefoot, especially without gradual build-up, carries a real risk of foot, calf and Achilles injury. Sprint Intervals and Walking exist in the catalog as safer options.","hidden":true,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
