{"id":"263a6d56-df28-50d0-b88f-61d171392f23","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Masseter Chewing","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Tongue training, swallowing and chewing","scheduled_time":"07:31:00","duration_minutes":2,"day_number":4,"sort_order":170,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_masseter_chewing","notes":"Dose: Guide suggests 20–30 chews per bite.\n1. Take a small bite of food.\n2. Chew slowly with a comfortable, alternating jaw movement.\n3. Avoid excessive clenching or very hard foods.\n4. Aim for around 20–30 chews before swallowing.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"67bde016-647c-524e-9eb1-be0b929a47d5","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Tongue T-Spot Hold","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Tongue training, swallowing and chewing","scheduled_time":"07:34:00","duration_minutes":2,"day_number":4,"sort_order":180,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_tongue_t_spot_hold","notes":"Dose: Archived version: 10–20 seconds × 2–3.\n1. Touch the tip of your tongue just behind the upper front teeth.\n2. Gently open and close the jaw while keeping that light contact.\n3. Keep the pressure light and the face relaxed.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
