{"id":"a8450216-f937-5e41-9238-a413316b77f9","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Hands-Free Fascia-Pulling Twist","item_type":"activity","kind":"action","category":"do","subtype":"exercise","group_name":"5. Twisting finish (2 min)","scheduled_time":"07:27:00","duration_minutes":2,"day_number":10,"sort_order":190,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_hands_free_fascia_pulling_twist","notes":"Suggested complete session: a synthesis of lower-risk elements from the catalogue, not an exact routine published by Oscar. Dose: A few slow turns each side; Oscar gives no verified total count.\n1. Step into a lunge with your weight over the front knee and the back heel lifted.\n2. Relax your face and breathe quietly through the nose. Keep your hands free (no thumbs in the mouth).\n3. Slowly turn your head first, then your spine, then your hips, within a comfortable range.\n4. Let the back heel pivot outward naturally as the body turns.\n5. Return to centre, then repeat on the other side.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"ad0f2a06-6a8a-57ed-8cab-f358532f7eb8","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Towel tongue pulling","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"Tongue training, swallowing and chewing","duration_minutes":2,"day_number":4,"sort_order":190,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_towel_tongue_pulling","notes":"Research-only, not for self-guided use. Described in Oscar's materials: Gripping the extended tongue with a towel and pulling it in different directions. Documented dose: 5–10 seconds × 2–3 rounds. Pulling the tongue with a towel can cause pain, tissue injury and irritation. Not suitable for self-guided use.","hidden":true,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"7a9a5b49-4924-52b6-b127-c96033c7252e","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Resting Tongue Posture (Mewing)","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"6. Oral and facial function (3–5 min)","scheduled_time":"07:29:00","duration_minutes":1,"day_number":10,"sort_order":200,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_resting_tongue_posture_mewing","notes":"Suggested complete session: a synthesis of lower-risk elements from the catalogue, not an exact routine published by Oscar. Dose: A habit through the day; no timed sets.\n1. Sit or stand with your head comfortably aligned.\n2. Let the jaw hang loose.\n3. Close your lips without pressing them together.\n4. Rest the tongue tip just behind the upper front teeth, without pushing on them, with the wider tongue resting lightly against the palate.\n5. Keep breathing quietly through the nose.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"aedc13ee-d7f7-57a7-b4ad-6e6697ef757f","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Tongue Clicks","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"6. Oral and facial function (3–5 min)","scheduled_time":"07:30:00","duration_minutes":1,"day_number":10,"sort_order":210,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_tongue_clicks","notes":"Suggested complete session: a synthesis of lower-risk elements from the catalogue, not an exact routine published by Oscar. Dose: Not specified.\n1. Open the mouth slightly.\n2. Press the whole tongue against the roof of the mouth.\n3. Form a light suction.\n4. Release the tongue quickly to make a click.\n5. Repeat while keeping the jaw relaxed.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"9a268f4c-59d8-50cf-8ed2-e6e0bb0de4c8","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Jaw Relaxation","item_type":"activity","kind":"action","category":"do","subtype":"hygiene","group_name":"6. Oral and facial function (3–5 min)","scheduled_time":"07:31:00","duration_minutes":2,"day_number":10,"sort_order":220,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_jaw_relaxation","notes":"Suggested complete session: a synthesis of lower-risk elements from the catalogue, not an exact routine published by Oscar. Gentle facial relaxation: let the jaw hang loose and rest the tongue lightly. This is an existing catalog activity; its full steps are on the activity.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"8cc91556-d868-5055-856c-e8f9e9d70da3","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Diaphragmatic breathing","item_type":"activity","kind":"action","category":"do","subtype":"wellness","group_name":"7. Breathing (2–5 min)","scheduled_time":"07:33:00","duration_minutes":2,"day_number":10,"sort_order":230,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_natmove_breathing","notes":"Suggested complete session: a synthesis of lower-risk elements from the catalogue, not an exact routine published by Oscar. Hands on the lower ribs; breathe in gently and let them expand; exhale without forcing. Ongoing habit. This is an existing catalog activity; its full steps are on the activity.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"ae7f4d53-ff09-53f2-93d4-100094f90abe","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Comfortable Nasal Breathing","item_type":"activity","kind":"action","category":"do","subtype":"wellness","group_name":"7. Breathing (2–5 min)","scheduled_time":"07:35:00","duration_minutes":2,"day_number":10,"sort_order":240,"recurrence_type":"daily","recurrence_interval_unit":"day","catalog_activity_id":"activity_oscar_comfortable_nasal_breathing","notes":"Suggested complete session: a synthesis of lower-risk elements from the catalogue, not an exact routine published by Oscar. Dose: Encouraged when the airway is clear.\n1. Make sure your nose is clear and breathing through it feels easy.\n2. Close your lips softly without pressing them together.\n3. Breathe in and out through your nose at an easy pace.\n4. If your nose is blocked or breathing feels hard, return to easy mouth breathing and see a clinician if it keeps happening.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"9a168955-61c6-577c-bf07-5ec87c7a086c","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Don't tape the mouth shut during sleep","item_type":"activity","kind":"rule_dont","category":"do","subtype":"wellness","scope":"inside","group_name":"Safety","sort_order":900,"recurrence_type":"daily","recurrence_interval_unit":"day","notes":"Especially with snoring, nasal obstruction or possible sleep apnea. Long-term facial reshaping through tape is not established.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"68b91301-c90d-54be-936a-020010ad2049","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Don't force anything inside the mouth or on the skull","item_type":"activity","kind":"rule_dont","category":"do","subtype":"wellness","scope":"inside","group_name":"Safety","sort_order":901,"recurrence_type":"daily","recurrence_interval_unit":"day","notes":"Forceful palate, gum, tongue or cranial pressure can cause dental movement, gum injury and jaw pain. The research-only techniques in this routine are not enabled for self-guided use.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"a085e5af-e050-5f24-a36d-7b4b64004643","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Don't strain a pause until you feel dizzy","item_type":"activity","kind":"rule_dont","category":"do","subtype":"wellness","scope":"inside","group_name":"Safety","sort_order":902,"recurrence_type":"daily","recurrence_interval_unit":"day","notes":"Never practise breath-holds in water, while driving or standing. Stop if you feel dizzy.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false},
{"id":"9ef360b9-85af-5660-bd1c-d2c2ffa49881","protocol_id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","display_name":"Stop if you feel pain, tingling, dizziness or unwell","item_type":"activity","kind":"rule_do","category":"do","subtype":"wellness","scope":"inside","group_name":"Safety","sort_order":903,"recurrence_type":"daily","recurrence_interval_unit":"day","notes":"This routine is educational, not medical advice. Ask a qualified clinician before starting if you have jaw, neck, dental, breathing or circulation problems.","hidden":false,"enabled":true,"has_children":false,"is_starter":false,"notifications_enabled":false}
]$oscar_items$::jsonb;
begin
  if exists (select 1 from public.protocols where id ='0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31') then
    raise notice 'Oscar Patel protocol already present, nothing to do';
    return;
  end if;

  select string_agg(a, ', ' order by a) into missing
  from (select distinct e->>'catalog_activity_id' as a from jsonb_array_elements(items) e where e->>'catalog_activity_id' is not null) used
  where not exists (select 1 from public.catalog_activities c where c.id = used.a);
  if missing is not null then
    raise exception 'Oscar Patel protocol needs these catalog activities first: %', missing;
  end if;

  insert into public.protocols (
    id, name, description, type, is_suggested, is_active, frequency, tags, source_attribution, sort_order, target_age_min, total_days, risk_level, effectiveness_evidence, contraindications, prerequisites, category, source, is_public, is_enabled, is_personal_routine, created_at, updated_at
  )
  select r.id, r.name, r.description, r.type, r.is_suggested, r.is_active, r.frequency, r.tags, r.source_attribution, r.sort_order, r.target_age_min, r.total_days, r.risk_level, r.effectiveness_evidence, r.contraindications, r.prerequisites, r.category, r.source, r.is_public, r.is_enabled, r.is_personal_routine, now(), now()
  from jsonb_populate_record(null::public.protocols, $oscar_protocol_row${"id":"0c5ca4a7-0e1f-4a52-9a0b-5c1c6c1f0a31","name":"Oscar Patel — Master Exercise Encyclopedia","description":"A master catalogue of the exercises Oscar Patel teaches: full-body spirals and twists, foot and fascia release, posture, tongue and swallowing drills, facial-muscle work, neck training and breathwork. Days 1–9 follow the nine categories of the catalogue, one category a day; Day 10 is a suggested complete session built from the lower-risk elements.\n\nThe techniques that rely on forceful pressure on the palate, gums, tongue or skull, deep abdominal pressure, small objects between the lips and facial taping are kept in the routine as research-only source material: they are stored but hidden, not scheduled and not enabled for self-guided use. Evidence is limited: tongue and swallowing exercises taught by a clinician have trial support for sleep apnea, but claims that these methods reshape adult facial bone are not supported.\n\nThis is educational, not medical advice.","type":"daily","is_suggested":false,"is_active":true,"frequency":"daily","tags":["oscar patel","face","fascia","posture","breathing","neck","tongue","myofunctional","encyclopedia"],"source_attribution":"Compiled on 25 October 2026 from Oscar Patel's public materials (his website, YouTube videos and social posts) and an unverified 93-page community document. Not written or endorsed by Oscar Patel.","sort_order":0,"target_age_min":18,"total_days":10,"risk_level":"moderate","effectiveness_evidence":"low","contraindications":["Jaw (TMJ) pain, dental work or braces: check with a dentist first","Neck pain, dizziness or arm symptoms: check with a clinician before the neck exercises","Breathing, heart or lung conditions: ask a clinician before the breathing exercises","Under 18, pregnancy or recent surgery: ask a clinician first"],"prerequisites":[],"category":"Fitness","source":"system","is_public":false,"is_enabled":false,"is_personal_routine":false}$oscar_protocol_row$::jsonb) r;

  insert into public.protocol_items (
    id, protocol_id, display_name, item_type, kind, category, subtype, scope, group_name, scheduled_time, duration_minutes, day_number, sort_order, recurrence_type, recurrence_interval_unit, catalog_activity_id, notes, hidden, enabled, has_children, is_starter, notifications_enabled, created_at
  )
  select r.id, r.protocol_id, r.display_name, r.item_type, r.kind, r.category, r.subtype, r.scope, r.group_name, r.scheduled_time, r.duration_minutes, r.day_number, r.sort_order, r.recurrence_type, r.recurrence_interval_unit, r.catalog_activity_id, r.notes, r.hidden, r.enabled, r.has_children, r.is_starter, r.notifications_enabled, now()
  from jsonb_populate_recordset(null::public.protocol_items, items) r;
end
$oscar_protocol$;
